mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("[5,2,10,4]","5,3.5,5,4.5"),
        ("[1,3]","1,2"),
        ("[1,2,3,4,5,6,7]","1,1.5,2,2.5,3,3.5,4"),
        ("[3,3,3,3,3,3,3]","3,3,3,3,3,3,3"),
        ("[8,7,6,5,4,3,2]","8,7.5,7,6.5,6,5.5,5"),
        ("  \n[5,2,10,4]\n  ","5,3.5,5,4.5"),
        ("\n[8,7,6,5,4,3,2]\n","8,7.5,7,6.5,6,5.5,5")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS two-heap-median");
}
